#define COLOR3 vec3(1.00, 0.98, 0.67) // Stronger yellow tone
#define COLOR2 vec3(0.361, 0.812, 0.565) // #5CCF90
#define COLOR4 vec3(0.514, 0.933, 0.757) // #83EEC1

float rand(vec2 p) {
    return fract(sin(dot(p, vec2(12.99, 78.233))) * 43758.545);
}

float noise(vec2 p) {
    vec2 f = fract(p);
    f = f * f * (3. - 2. * f);
    vec2 i = floor(p);
    return mix(mix(rand(i + vec2(0, 0)), 
                   rand(i + vec2(1, 0)), f.x),
               mix(rand(i + vec2(0, 1)), 
                   rand(i + vec2(1, 1)), f.x), f.y);
}

float fbm_streaks(vec2 p) {
    float v = 0.;
    float a = 0.5;
    mat2 rot = mat2(0.8, -0.6, 0.6, 0.8); // Rotation matrix for directional noise
    for (int i = 0; i < 7; ++i) {
        v += a * noise(p);
        p = rot * p * vec2(1.5, 0.7); // Stretch coordinates to create streaks
        a *= 0.5;
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 p = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    float time = iTime * 0.1;

    float f = fbm_streaks(p * 1.0 + time);        // Streaky fbm with lower frequency
    float f2 = fbm_streaks(p * 0.2 - time * 1.5 + f);

    vec2 q = vec2(f, f2);

    float final = fbm_streaks(p * 1.0 + q * 2.0); // Final pattern with streaks

    // Color blending without COLOR1
    vec3 col = mix(COLOR2, COLOR3, smoothstep(0.2, 0.9, final)); // Stronger yellow blend
    col = mix(col, COLOR4, smoothstep(0.6, 1.0, final));

    col = pow(col, vec3(1.5)); // Lower brightness adjustment
    col = mix(col, col * col * (3.0 - 2.0 * col), 0.15); // Increased saturation step

    fragColor = vec4(col, 1.0);
}
